import {
  ArrowLeft, ArrowRight, Bell, Bold, BriefcaseBusiness, CalendarDays, CheckCircle2, Eye, EyeOff, GripVertical, Italic, LayoutGrid, Link2, List, ListOrdered, LogOut, Menu, Plus, Search, Underline, UserPlus, Users, X,
} from "lucide-react";
import { type CSSProperties, type DragEvent, type FormEvent, type ReactNode, useEffect, useMemo, useRef, useState } from "react";
import { createInvitedUser, hasFirebaseConfig, signInWithEmail, signUpWithEmail, signOutFirebase, watchAuth } from "./services/firebaseAuth";
import { createRemoteWorkspace, getRemoteUserProfile, getRemoteWorkspace, getRemoteWorkspaceMembers, hasFirestore, saveRemoteUserProfile, saveRemoteWorkspacePatch } from "./services/firestoreData";

type Role = "employer" | "admin" | "employee";
type TaskStatus = "assigned" | "ongoing" | "completed";
type TaskPriority = "low" | "medium" | "high";
type ViewMode = "projects" | "board" | "calendar";
type AuthMode = "signup" | "signin";
type UserRecord = { id: string; name: string; email: string; password?: string; role: Role; designation: string; workspaceId: string; companyName: string };
type TaskRecord = { id: string; title: string; description: string; employeeId: string; employeeIds?: string[]; createdBy?: string; assignedDate: string; dueDate: string; status: TaskStatus; priority?: TaskPriority; projectId?: string; isPrivate?: boolean };
type ProjectAttachment = { id: string; name: string; kind: string; url?: string };
type ProjectRecord = { id: string; name: string; description: string; color: string; attachments?: ProjectAttachment[] };
type WorkspaceRecord = { id: string; companyName: string; employerId: string; tasks: TaskRecord[]; projects?: ProjectRecord[] };

const KEYS = { users: "operion-mvp-users", workspaces: "operion-mvp-workspaces", session: "operion-mvp-session" };
const COLUMNS: { status: TaskStatus; title: string }[] = [{ status: "assigned", title: "Assigned" }, { status: "ongoing", title: "Ongoing" }, { status: "completed", title: "Completed" }];
const COLORS = ["#d8f3dc", "#dbeafe", "#fef3c7", "#fce7f3", "#ede9fe"];

function taskHasAssignee(task: TaskRecord, employeeId: string) {
  return task.employeeId === employeeId || task.employeeIds?.includes(employeeId) === true;
}

function greeting() {
  const hour = new Date().getHours();
  if (hour < 12) return "Good morning";
  if (hour < 16) return "Good afternoon";
  return "Good evening";
}

function dashboardDate() {
  return new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" }).format(new Date());
}

function firstName(name: string) {
  return name.trim().split(/\s+/)[0] ?? "";
}


function ProjectMvpApp() {
  const [users, setUsers] = usePersistentState<UserRecord[]>(KEYS.users, []);
  const [workspaces, setWorkspaces] = usePersistentState<WorkspaceRecord[]>(KEYS.workspaces, []);
  const [session, setSession] = usePersistentState<{ email: string } | null>(KEYS.session, null);
  const [authMode, setAuthMode] = useState<AuthMode>("signup");
  const [authReady, setAuthReady] = useState(!hasFirebaseConfig);
  const [viewMode, setViewMode] = useState<ViewMode>("projects");
  const [activeProjectId, setActiveProjectId] = useState("");
  const [message, setMessage] = useState(""); const [error, setError] = useState("");
  const [dialog, setDialog] = useState<"employee" | "project" | "task" | null>(null);
  const [showCreateMenu, setShowCreateMenu] = useState(false); const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const navigationReady = useRef(false);
  const remoteWorkspaceIds = useRef(new Set<string>());
  const restoringNavigation = useRef(false);
  const [detailTaskId, setDetailTaskId] = useState<string | null>(null);
  const [taskProjectId, setTaskProjectId] = useState<string | null | undefined>(undefined);
  const [confirmDialog, setConfirmDialog] = useState<{ title: string; message: string; event: string; detail: string } | null>(null);
  const [assigneeIds, setAssigneeIds] = useState<string[]>([]); const [selectedEmployeeId, setSelectedEmployeeId] = useState("");
  const [dragTaskId, setDragTaskId] = useState<string | null>(null); const [dropStatus, setDropStatus] = useState<TaskStatus | null>(null); const [dropEmployeeId, setDropEmployeeId] = useState<string | null>(null);
  const user = useMemo(() => session ? users.find((item) => item.email === normalizeEmail(session.email)) ?? null : null, [session, users]);
  const workspace = useMemo(() => user ? workspaces.find((item) => item.id === user.workspaceId) ?? null : null, [user, workspaces]);
  const employer = user?.role === "employer" || user?.role === "admin";
  const members = useMemo(() => workspace ? users.filter((item) => item.workspaceId === workspace.id && (item.role === "employee" || item.role === "admin")).sort((a, b) => a.name.localeCompare(b.name)) : [], [users, workspace]);
  const workspaceOwner = useMemo(() => workspace ? users.find((item) => item.id === workspace.employerId) ?? null : null, [users, workspace]);
  const lookup = useMemo(() => new Map([...(workspaceOwner ? [[workspaceOwner.id, workspaceOwner] as const] : []), ...(user ? [[user.id, user] as const] : []), ...members.map((item) => [item.id, item] as const)]), [members, user, workspaceOwner]);
  const projects = useMemo(() => workspace ? getProjects(workspace) : [], [workspace]);
  const project = projects.find((item) => item.id === activeProjectId) ?? projects[0] ?? null;
  const myTasks = workspace?.tasks.filter((task) => user ? taskHasAssignee(task, user.id) : false) ?? [];
  const allTasks = employer ? workspace?.tasks ?? [] : myTasks;
  const tasks = allTasks.filter((task) => !task.isPrivate && (task.projectId ?? defaultProjectId(workspace?.id ?? "")) === project?.id);
  const selectedEmployee = members.find((item) => item.id === selectedEmployeeId) ?? members[0] ?? null;
  const selectedEmployeeTasks = selectedEmployee ? (workspace?.tasks ?? []).filter((task) => !task.isPrivate && taskHasAssignee(task, selectedEmployee.id) && (task.projectId ?? defaultProjectId(workspace?.id ?? "")) === project?.id) : [];

  const hydrateRemoteAccount = async (email: string) => {
    const profile = await getRemoteUserProfile<UserRecord>(email);
    if (!profile?.workspaceId) throw new Error("Your account profile is missing a workspace. Ask the employer to invite you again.");
    const remoteWorkspace = await getRemoteWorkspace<WorkspaceRecord>(profile.workspaceId);
    if (!remoteWorkspace) throw new Error("Your workspace could not be found.");
    const remoteMembers = await getRemoteWorkspaceMembers<UserRecord>(profile.workspaceId);
    const membersById = new Map(remoteMembers.map((member) => [member.id, { ...member, password: "" }]));
    membersById.set(profile.id, { ...profile, password: "" });
    setUsers(Array.from(membersById.values()));
    setWorkspaces([{ ...remoteWorkspace, tasks: remoteWorkspace.tasks ?? [], projects: remoteWorkspace.projects ?? [] }]);
    setSession({ email: normalizeEmail(email) });
    remoteWorkspaceIds.current.add(remoteWorkspace.id);
  };

  useEffect(() => {
    if (!hasFirebaseConfig) return undefined;
    return watchAuth((firebaseUser) => {
      setAuthReady(true);
      if (!firebaseUser) {
        setSession(null);
        return;
      }
      void getRemoteUserProfile<UserRecord>(firebaseUser.email ?? "")
        .then((profile) => profile ? hydrateRemoteAccount(firebaseUser.email ?? "") : undefined)
        .catch((reason: unknown) => {
          setError(reason instanceof Error ? reason.message : "Could not load your workspace.");
        });
    });
  }, []);

  useEffect(() => {
    if (!hasFirestore || !workspace || !remoteWorkspaceIds.current.has(workspace.id)) return;
    void saveRemoteWorkspacePatch(workspace.id, { tasks: workspace.tasks, projects: workspace.projects ?? [] }).catch((reason: unknown) => {
      console.warn("Could not sync workspace changes to Firestore.", reason);
    });
  }, [workspace]);

  useEffect(() => {
    if (!hasFirestore || !workspace) return;
    users.filter((member) => member.workspaceId === workspace.id).forEach((member) => {
      const { password: _password, ...remoteProfile } = member;
      void saveRemoteUserProfile(remoteProfile).catch((reason: unknown) => console.warn("Could not sync member profile.", reason));
    });
  }, [users, workspace]);

  useEffect(() => { if (!activeProjectId && projects[0]) setActiveProjectId(projects[0].id); }, [activeProjectId, projects]);
  useEffect(() => { const state = { operionView: viewMode, projectId: activeProjectId }; if (!navigationReady.current) { window.history.replaceState(state, "", window.location.href); window.history.pushState(state, "", window.location.href); navigationReady.current = true; return; } if (restoringNavigation.current) { restoringNavigation.current = false; return; } window.history.pushState(state, "", window.location.href); }, [viewMode, activeProjectId]);
  useEffect(() => { const restoreNavigation = (event: PopStateEvent) => { const state = event.state as { operionView?: ViewMode; projectId?: string } | null; restoringNavigation.current = true; setViewMode(state?.operionView ?? "projects"); setActiveProjectId(state?.projectId ?? ""); setShowCreateMenu(false); }; window.addEventListener("popstate", restoreNavigation); return () => window.removeEventListener("popstate", restoreNavigation); }, []);
  useEffect(() => { document.documentElement.style.setProperty("--operion-greeting-name", JSON.stringify(user?.name ?? "")); document.documentElement.style.setProperty("--operion-greeting-date", JSON.stringify(new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" }).format(new Date()))); }, [user?.name]);
  useEffect(() => { if (!selectedEmployeeId && members[0]) setSelectedEmployeeId(members[0].id); }, [members, selectedEmployeeId]);
  useEffect(() => { if (!message) return undefined; const timer = window.setTimeout(() => setMessage(""), 2600); return () => window.clearTimeout(timer); }, [message]);
  useEffect(() => { const closeCreateMenu = (event: PointerEvent) => { if (!(event.target instanceof Element)) return; if (!event.target.closest(".create-wrap")) setShowCreateMenu(false); }; document.addEventListener("pointerdown", closeCreateMenu); return () => document.removeEventListener("pointerdown", closeCreateMenu); }, []);
  useEffect(() => { if (dialog === "task" && !employer && taskProjectId !== null) setTaskProjectId(null); }, [dialog, employer, taskProjectId]);
  useEffect(() => { const openTask = (event: Event) => { const privateTask = (event as CustomEvent<string | undefined>).detail === "private"; setTaskProjectId(privateTask ? null : project?.id ?? null); setDialog("task"); }; const openDetail = (event: Event) => setDetailTaskId((event as CustomEvent<string>).detail); const openDate = (event: Event) => window.dispatchEvent(new CustomEvent("operion-show-task-date", { detail: (event as CustomEvent<string>).detail })); window.addEventListener("operion-create-task", openTask); window.addEventListener("operion-open-task", openDetail); window.addEventListener("operion-open-task-date", openDate); return () => { window.removeEventListener("operion-create-task", openTask); window.removeEventListener("operion-open-task", openDetail); window.removeEventListener("operion-open-task-date", openDate); }; }, [workspace?.id, project?.id]);
  useEffect(() => { const moveTask = (event: Event) => { const detail = (event as CustomEvent<{ taskId: string; status: TaskStatus }>).detail; update((item) => ({ ...item, tasks: item.tasks.map((task) => task.id === detail.taskId ? { ...task, status: detail.status } : task) })); }; const updateDate = (event: Event) => { const detail = (event as CustomEvent<{ taskId: string; dueDate?: string; assignedDate?: string }>).detail; update((item) => ({ ...item, tasks: item.tasks.map((task) => task.id === detail.taskId ? { ...task, ...(detail.dueDate !== undefined ? { dueDate: detail.dueDate } : {}), ...(detail.assignedDate !== undefined ? { assignedDate: detail.assignedDate } : {}) } : task) })); }; const deleteTask = (event: Event) => { const taskId = (event as CustomEvent<string>).detail; if (!taskId) return; setConfirmDialog({ title: "Delete task", message: "Delete this task?", event: "operion-confirm-delete-task", detail: taskId }); }; window.addEventListener("operion-update-task", moveTask); window.addEventListener("operion-update-task-date", updateDate); window.addEventListener("operion-delete-task", deleteTask); return () => { window.removeEventListener("operion-update-task", moveTask); window.removeEventListener("operion-update-task-date", updateDate); window.removeEventListener("operion-delete-task", deleteTask); }; }, [workspace?.id]);

  useEffect(() => { const confirmDeleteTask = (event: Event) => { const taskId = (event as CustomEvent<string>).detail; update((item) => ({ ...item, tasks: item.tasks.filter((task) => task.id !== taskId) })); setDetailTaskId(null); setMessage("Task deleted."); }; const deleteTasksSilently = (event: Event) => { const taskIds = (event as CustomEvent<string[]>).detail; update((item) => ({ ...item, tasks: item.tasks.filter((task) => !taskIds.includes(task.id)) })); }; window.addEventListener("operion-confirm-delete-task", confirmDeleteTask); window.addEventListener("operion-delete-tasks-silently", deleteTasksSilently); return () => { window.removeEventListener("operion-confirm-delete-task", confirmDeleteTask); window.removeEventListener("operion-delete-tasks-silently", deleteTasksSilently); }; }, [workspace?.id]);
  const update = (mutate: (item: WorkspaceRecord) => WorkspaceRecord) => { if (workspace) setWorkspaces((items) => items.map((item) => item.id === workspace.id ? mutate(item) : item)); };
  useEffect(() => { const removeMember = (event: Event) => { const memberId = (event as CustomEvent<string>).detail; setUsers((items) => items.filter((item) => item.id !== memberId)); }; window.addEventListener("operion-remove-member", removeMember); return () => window.removeEventListener("operion-remove-member", removeMember); }, []);
  useEffect(() => { const updateMemberRole = (event: Event) => { const detail = (event as CustomEvent<{ memberId: string; role: Role }>).detail; if (user?.role !== "employer" || !detail?.memberId) return; setUsers((items) => items.map((item) => item.id === detail.memberId && item.role !== "employer" ? { ...item, role: detail.role } : item)); }; window.addEventListener("operion-update-member-role", updateMemberRole); return () => window.removeEventListener("operion-update-member-role", updateMemberRole); }, [user?.role]);
  useEffect(() => { const removeProject = (event: Event) => { const projectId = (event as CustomEvent<string>).detail; if (!projectId) return; setConfirmDialog({ title: "Delete project", message: "Delete this project and all of its tasks?", event: "operion-confirm-delete-project", detail: projectId }); }; window.addEventListener("operion-delete-project", removeProject); return () => window.removeEventListener("operion-delete-project", removeProject); }, [workspace?.id]);
  useEffect(() => { const confirmDeleteProject = (event: Event) => { const projectId = (event as CustomEvent<string>).detail; setWorkspaces((items) => items.map((item) => item.id === workspace?.id ? { ...item, projects: (item.projects ?? []).filter((project) => project.id !== projectId), tasks: item.tasks.filter((task) => task.projectId !== projectId) } : item)); setActiveProjectId(""); setViewMode("projects"); setMessage("Project deleted."); }; window.addEventListener("operion-confirm-delete-project", confirmDeleteProject); return () => window.removeEventListener("operion-confirm-delete-project", confirmDeleteProject); }, [workspace?.id]);
  const closeDialog = () => { setDialog(null); setTaskProjectId(undefined); setError(""); };
  const signup = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setError(""); const form = new FormData(event.currentTarget); const companyName = value(form, "companyName"), name = value(form, "employerName"), email = normalizeEmail(value(form, "email")), password = value(form, "password"); if (!companyName || !name || !email || !password) return setError("Please fill in every field."); if (findUser(users, email)) return setError("That email already exists. Please sign in instead."); const employerId = id(), workspaceId = id(); try { const firebaseUser = hasFirebaseConfig ? await signUpWithEmail(name, email, password) : null; const remoteEmployerId = firebaseUser?.uid ?? employerId; const profile = { id: remoteEmployerId, name, email, role: "employer" as const, designation: "Employer", workspaceId, companyName }; const initialWorkspace = { id: workspaceId, companyName, employerId: remoteEmployerId, tasks: [], projects: [] }; if (hasFirestore) { await createRemoteWorkspace({ ...profile, name }, initialWorkspace); remoteWorkspaceIds.current.add(workspaceId); } setUsers((items) => [...items, { ...profile, password }]); setWorkspaces((items) => [...items, initialWorkspace]); setSession({ email }); setMessage(`${companyName} workspace created.`); event.currentTarget.reset(); } catch (reason: unknown) { setError(reason instanceof Error ? reason.message : "Could not create the account."); } };
  const login = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setError(""); const form = new FormData(event.currentTarget), email = normalizeEmail(value(form, "email")), password = value(form, "password"); try { if (hasFirebaseConfig) { const firebaseUser = await signInWithEmail(email, password); await hydrateRemoteAccount(firebaseUser.email ?? email); const remoteProfile = await getRemoteUserProfile<UserRecord>(firebaseUser.email ?? email); setMessage(`Welcome back, ${remoteProfile?.name ?? firebaseUser.displayName ?? email}.`); } else { const found = findUser(users, email); if (!found || found.password !== password) return setError("Invalid email or password."); setSession({ email }); setMessage(`Welcome back, ${found.name}.`); } event.currentTarget.reset(); } catch (reason: unknown) { setError(reason instanceof Error ? reason.message : "Invalid email or password."); } };
  const invite = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget), name = value(form, "name"), designation = value(form, "designation"), email = normalizeEmail(value(form, "email")), password = value(form, "password"); if (!workspace || !name || !designation || !email || !password) return setError("Please complete every employee field."); if (findUser(users, email)) return setError("That email already has an account. Duplicate accounts are not allowed."); try { const firebaseUser = hasFirebaseConfig ? await createInvitedUser(name, email, password) : null; const member = { id: firebaseUser?.uid ?? id(), name, email, password: hasFirebaseConfig ? "" : password, role: "employee" as const, designation, workspaceId: workspace.id, companyName: workspace.companyName }; if (hasFirestore) { const { password: _password, ...remoteProfile } = member; await saveRemoteUserProfile(remoteProfile); } setUsers((items) => [...items, member]); setMessage(`${name} has been added to the team.`); closeDialog(); event.currentTarget.reset(); } catch (reason: unknown) { setError(reason instanceof Error ? reason.message : "Could not add this employee."); } };
  const createProject = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget), name = value(form, "name"), description = value(form, "description"), links = Array.from(document.querySelectorAll<HTMLInputElement>("[data-project-link]")).map((input) => input.value.trim()).filter(Boolean); if (!workspace || !name) return setError("Add a project name first."); const files = Array.from(document.querySelectorAll<HTMLInputElement>("[data-project-file]")).flatMap((input) => Array.from(input.files ?? [])); const fileData = await Promise.all(files.map(async (file) => ({ id: id(), name: file.name, kind: file.type || "file", url: await readFileData(file) }))); const attachments = [...fileData, ...links.map((link) => ({ id: id(), name: link, kind: "link", url: link }))]; const created = { id: id(), name, description, color: COLORS[projects.length % COLORS.length], attachments }; update((item) => ({ ...item, projects: [...getProjects(item), created] })); setActiveProjectId(created.id); setViewMode("board"); setMessage(`${name} project created.`); closeDialog(); event.currentTarget.reset(); };
  const createTask = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget), title = value(form, "title"), description = value(form, "description"), employeeIds = taskProjectId === null ? [user?.id ?? ""] : form.getAll("employeeId").map(String), employeeId = employeeIds[0] ?? "", assignedDate = value(form, "assignedDate") || today(), dueDate = value(form, "dueDate"), priority = (value(form, "priority") || "medium") as TaskPriority, selectedProjectId = taskProjectId === null ? "" : value(form, "projectId") || taskProjectId || project?.id || ""; if (!workspace || !title || !description || !employeeId || !dueDate) return setError("Complete the task details and choose an assignee."); const taskId = id(), selectedProject = projects.find((item) => item.id === selectedProjectId); update((item) => ({ ...item, tasks: [{ id: taskId, title, description, employeeId, assignedDate, dueDate, status: "assigned", priority, employeeIds, createdBy: user?.id ?? "", ...(selectedProjectId ? { projectId: selectedProjectId } : {}), ...(taskProjectId === null ? { isPrivate: true } : {}) }, ...item.tasks] })); setMessage(selectedProject ? `Task added to ${selectedProject.name}.` : "Private task added."); closeDialog(); event.currentTarget.reset(); window.setTimeout(() => window.dispatchEvent(new CustomEvent("operion-open-task", { detail: taskId })), 0); };
  const moveStatus = (taskId: string, status: TaskStatus) => { update((item) => ({ ...item, tasks: item.tasks.map((task) => task.id === taskId ? { ...task, status } : task) })); setMessage(`Task moved to ${status}.`); };
  const reassign = (taskId: string, employeeId: string) => { const member = members.find((item) => item.id === employeeId); if (!member) return; update((item) => ({ ...item, tasks: item.tasks.map((task) => task.id === taskId ? { ...task, employeeId } : task) })); setMessage(`Task reassigned to ${member.name}.`); };
  const logout = () => { if (hasFirebaseConfig) void signOutFirebase(); setSession(null); setViewMode("projects"); setActiveProjectId(""); setMessage(""); setDragTaskId(null); };
  if (!authReady || !user || !workspace) return <AuthScreen mode={authMode} error={error} message={message} onModeChange={setAuthMode} onSignup={signup} onLogin={login} />;
  return <main className={`app-shell ${sidebarCollapsed ? "sidebar-collapsed" : ""}`}><Sidebar collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((open) => !open)} employer={Boolean(employer)} owner={user?.role === "employer"} projects={projects} activeProjectId={project?.id ?? ""} onHome={() => { setViewMode("projects"); setShowCreateMenu(false); }} onProjects={() => setViewMode("projects")} onOpenProject={(projectId) => { setActiveProjectId(projectId); setViewMode("board"); }} onInvite={() => setDialog("employee")} /><div className="workspace-content"><header className="topbar">{sidebarCollapsed && <button className="sidebar-toggle-button" type="button" onClick={() => setSidebarCollapsed(false)} aria-label="Expand sidebar" title="Expand sidebar"><Menu size={19} /></button>}<div className="mobile-brand"><div><p className="eyebrow">Operion OS</p><h1>{workspace.companyName}</h1></div></div><div className="search-box"><span>⌕</span><input aria-label="Search" placeholder="Search" /><kbd>Ctrl</kbd><kbd>K</kbd></div><div className="topbar-actions"><div className="create-wrap"><button className="create-button" type="button" onClick={() => setShowCreateMenu((open) => !open)}><Plus size={17} />Create</button>{showCreateMenu && <div className="create-menu"><button type="button" onClick={() => { setTaskProjectId(undefined); setDialog("task"); setShowCreateMenu(false); }}><CheckCircle2 size={17} />Task</button>{employer && <button type="button" onClick={() => { setDialog("project"); setShowCreateMenu(false); }}><LayoutGrid size={17} />Project</button>}</div>}</div>{user?.role === "employer" && <button className="icon-button" title="Add employee" type="button" onClick={() => setDialog("employee")}><UserPlus size={18} /></button>}<div className="pill"><Users size={16} />{members.length}</div><button className="ghost-button" type="button" onClick={logout}><LogOut size={16} />Logout</button></div></header>{message && <div className="banner success">{message}</div>}{error && <div className="banner error">{error}</div>}{viewMode === "projects" ? <ProjectHome employer={Boolean(employer)} projects={projects} tasks={workspace?.tasks ?? []} lookup={lookup} onNewProject={() => setDialog("project")} onOpen={(projectId) => { setActiveProjectId(projectId); setViewMode("board"); }} /> : <><div className="subnav"><button className="back-button" type="button" onClick={() => setViewMode("projects")}><ArrowLeft size={16} />Projects</button><div><p className="eyebrow">Project</p><strong>{project?.name}</strong></div><div className="mode-switch"><button className={viewMode === "board" ? "active" : ""} type="button" onClick={() => setViewMode("board")}><LayoutGrid size={16} />Board</button><button className={viewMode === "calendar" ? "active" : ""} type="button" onClick={() => setViewMode("calendar")}><CalendarDays size={16} />Calendar</button></div></div>{viewMode === "board" ? <ProjectBoard employer={Boolean(employer)} user={user} project={project} tasks={tasks} members={members} lookup={lookup} onAddTask={() => { setTaskProjectId(project?.id ?? null); setDialog("task"); }} onMove={moveStatus} onReassign={reassign} dragTaskId={dragTaskId} dropStatus={dropStatus} dropEmployeeId={dropEmployeeId} setDragTaskId={setDragTaskId} setDropStatus={setDropStatus} setDropEmployeeId={setDropEmployeeId} selectedEmployee={selectedEmployee} selectedEmployeeTasks={selectedEmployeeTasks} onSelectEmployee={setSelectedEmployeeId} /> : <CalendarBoard tasks={tasks} lookup={lookup} />}</>}{dialog === "employee" && <Modal title="Add employee" onClose={closeDialog}><form className="stack" onSubmit={invite}><input name="name" placeholder="Employee name" required /><input name="designation" placeholder="Designation" required /><input name="email" type="email" placeholder="Employee email" required /><PasswordField name="password" placeholder="Password" /><button className="primary-button" type="submit"><UserPlus size={16} />Add employee</button></form></Modal>}{dialog === "project" && <Modal title="Create project" onClose={closeDialog}><form className="stack" onSubmit={createProject}><input name="name" placeholder="Project name" required /><textarea name="description" placeholder="What is this project about?" rows={3} /><button className="primary-button" type="submit"><Plus size={16} />Create project</button></form></Modal>}{dialog === "task" && <TaskCreationModal taskProjectId={taskProjectId} project={project} projects={projects} employer={Boolean(employer)} user={user} members={members} assigneeIds={assigneeIds} setAssigneeIds={setAssigneeIds} onClose={closeDialog} onSubmit={createTask} />}{confirmDialog && <Modal title={confirmDialog.title} onClose={() => setConfirmDialog(null)}><p className="confirm-message">{confirmDialog.message}</p><div className="confirm-actions"><button className="secondary-button" type="button" onClick={() => setConfirmDialog(null)}>Cancel</button><button className="danger-button" type="button" onClick={() => { window.dispatchEvent(new CustomEvent(confirmDialog.event, { detail: confirmDialog.detail })); setConfirmDialog(null); }}>Confirm</button></div></Modal>}</div></main>;
}

function AuthScreen({ mode, error, message, onModeChange, onSignup, onLogin }: { mode: AuthMode; error: string; message: string; onModeChange: (mode: AuthMode) => void; onSignup: (event: FormEvent<HTMLFormElement>) => void; onLogin: (event: FormEvent<HTMLFormElement>) => void }) { return <main className="auth-shell"><section className="auth-card"><div className="brand-lockup"><div><p className="eyebrow">Operion OS</p><h1>Project management MVP</h1></div></div><p className="auth-copy">Create an employer workspace, invite your team, and manage work by project.</p><div className="mode-switch compact"><button className={mode === "signup" ? "active" : ""} type="button" onClick={() => onModeChange("signup")}>Employer signup</button><button className={mode === "signin" ? "active" : ""} type="button" onClick={() => onModeChange("signin")}>Sign in</button></div>{mode === "signup" ? <form className="stack" onSubmit={onSignup}><input name="companyName" placeholder="Company name" required /><input name="employerName" placeholder="Your name" required /><input name="email" type="email" placeholder="Employer email" required /><PasswordField name="password" placeholder="Password" /><button className="primary-button" type="submit">Create employer account<ArrowRight size={16} /></button></form> : <form className="stack" onSubmit={onLogin}><input name="email" type="email" placeholder="Email" required /><PasswordField name="password" placeholder="Password" /><button className="primary-button" type="submit">Sign in<ArrowRight size={16} /></button></form>}{error && <div className="banner error">{error}</div>}{message && <div className="banner success">{message}</div>}<p className="auth-note">Employees join through an employer invitation.</p></section></main>; }

function PasswordField({ name, placeholder }: { name: string; placeholder: string }) { const [visible, setVisible] = useState(false); return <div className="password-field"><input name={name} type={visible ? "text" : "password"} placeholder={placeholder} required /><button type="button" className="password-toggle" onClick={() => setVisible((value) => !value)} aria-label={visible ? "Hide password" : "Show password"} title={visible ? "Hide password" : "Show password"}>{visible ? <EyeOff size={17} /> : <Eye size={17} />}</button></div>; }

function ProjectHome({ employer, projects, tasks, onNewProject, onOpen, lookup }: { employer: boolean; projects: ProjectRecord[]; tasks: TaskRecord[]; onNewProject: () => void; onOpen: (id: string) => void; lookup: Map<string, UserRecord> }) { const session = load<{ email: string } | null>(KEYS.session, null); const currentUser = load<UserRecord[]>(KEYS.users, []).find((item) => item.email === normalizeEmail(session?.email ?? "")); const [projectFilter, setProjectFilter] = useState<"recent" | "browse">("recent"); const [browseOpen, setBrowseOpen] = useState(false); const shownProjects = projectFilter === "recent" ? [...projects].reverse() : projects; return <section className="project-home"><div className="section-heading"><div><p className="home-date">{dashboardDate()}</p><h2><span className="greeting-text">{greeting()}</span>, <span className="owner-name">{firstName(currentUser?.name ?? "")}</span></h2></div>{employer && <button className="primary-button compact-button" type="button" onClick={onNewProject}><Plus size={16} />New project</button>}</div><div className="dashboard-grid"><MyTasksCard tasks={tasks.filter((task) => currentUser ? taskHasAssignee(task, currentUser.id) : false)} employer={employer} lookup={lookup} /><section className="dashboard-card projects-summary"><div className="dashboard-card-head"><div><h3>Projects</h3><div className="projects-view-controls"><button className={projectFilter === "recent" ? "active" : ""} type="button" onClick={() => { setProjectFilter("recent"); setBrowseOpen(false); }}>Recents</button><button className={projectFilter === "browse" ? "active" : ""} type="button" onClick={() => { setProjectFilter("browse"); setBrowseOpen((open) => !open); }}>Browse projects</button>{browseOpen && <div className="browse-projects-menu">{projects.map((item) => <button type="button" key={item.id} onClick={() => { onOpen(item.id); setBrowseOpen(false); }}><span className="browse-project-dot" style={{ background: item.color }} />{item.name}</button>)}</div>}</div></div></div><div className="project-grid compact-project-grid">{employer && <button className="project-card create-project-card" type="button" onClick={onNewProject}><span className="project-icon"><Plus size={22} /></span><strong>Create project</strong></button>}{shownProjects.map((item, index) => { const count = tasks.filter((task) => !task.isPrivate && task.projectId === item.id).length; return <button className="project-card" key={item.id} type="button" onClick={() => onOpen(item.id)}><span className="project-icon" style={{ background: COLORS[(index + (employer ? 0 : 1)) % COLORS.length] }}><LayoutGrid size={22} /></span><span className="project-card-copy"><strong>{item.name}</strong><small>{count} task{count === 1 ? "" : "s"}</small></span></button>; })}</div></section></div>{employer && <PeopleCard employer={employer} tasks={tasks} projectCount={projects.length} />}</section>; }

function PeopleCard({ employer, tasks, projectCount }: { employer: boolean; tasks: TaskRecord[]; projectCount: number }) { const [selected, setSelected] = useState<string[]>([]); const [roleOverrides, setRoleOverrides] = useState<Record<string, Role>>({}); const [removed, setRemoved] = useState<string[]>([]); const session = load<{ email: string } | null>(KEYS.session, null); const users = load<UserRecord[]>(KEYS.users, []); const current = users.find((user) => user.email === normalizeEmail(session?.email ?? "")); const members = users.filter((user) => user.workspaceId === current?.workspaceId && (user.role === "employee" || user.role === "admin") && !removed.includes(user.id)); const workspaceTasks = load<WorkspaceRecord[]>(KEYS.workspaces, []).find((item) => item.id === current?.workspaceId)?.tasks ?? []; const canEditRoles = current?.role === "employer"; if (current?.role === "admin") return null; if (!employer) return <section className="dashboard-card people-summary"><div className="dashboard-card-head"><div><h3>Project pulse</h3><span className="muted-label">Your assigned work</span></div></div><div className="people-row"><span className="avatar-dot">{projectCount}</span><span>{tasks.length} task{tasks.length === 1 ? "" : "s"} across your projects</span></div></section>; return <section className="dashboard-card people-summary"><div className="dashboard-card-head"><div><h3>People</h3><span className="muted-label">Team overview</span></div>{selected.length > 0 && <button className="delete-team-button" type="button" onClick={() => { if (window.confirm(`Remove ${selected.length} selected employee${selected.length === 1 ? "" : "s"} from the team?`)) { setRemoved((currentRemoved) => [...currentRemoved, ...selected]); selected.forEach((memberId) => window.dispatchEvent(new CustomEvent("operion-remove-member", { detail: memberId }))); setSelected([]); } }}>Delete</button>}</div><div className="people-list">{members.length ? members.map((member) => { const memberTasks = workspaceTasks.filter((task) => taskHasAssignee(task, member.id)); return <label className="person-row" key={member.id}><input type="checkbox" checked={selected.includes(member.id)} onChange={(event) => setSelected((currentSelection) => event.target.checked ? [...currentSelection, member.id] : currentSelection.filter((id) => id !== member.id))} /><span className="person-avatar">{initials(member.name)}</span><span className="person-name">{member.name}<small>{member.designation}</small></span><select className="person-role" aria-label={`Role for ${member.name}`} value={roleOverrides[member.id] ?? member.role} disabled={!canEditRoles} onChange={(event) => { const role = event.target.value as Role; setRoleOverrides((items) => ({ ...items, [member.id]: role })); window.dispatchEvent(new CustomEvent("operion-update-member-role", { detail: { memberId: member.id, role } })); }}><option value="employee">Team access</option><option value="admin">Admin access</option></select><span className="person-stats"><span>{memberTasks.filter((task) => task.status === "assigned").length} assigned</span><span>{memberTasks.filter((task) => task.status === "ongoing").length} ongoing</span><span>{memberTasks.filter((task) => task.status === "completed").length} completed</span></span></label>; }) : <div className="empty-state small">No team members yet.</div>}</div></section>; }

function DatePicker({ task, onClose }: { task: TaskRecord; onClose: () => void }) { const [tab, setTab] = useState<"start" | "due">("due"); const [month, setMonth] = useState(() => new Date(`${task.dueDate || task.assignedDate}T00:00:00`)); const selected = tab === "start" ? task.assignedDate : task.dueDate; const first = new Date(month.getFullYear(), month.getMonth(), 1); const offset = first.getDay(); const days = new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate(); const cells = Array.from({ length: Math.ceil((offset + days) / 7) * 7 }, (_, index) => { const day = index - offset + 1; return day > 0 && day <= days ? `${month.getFullYear()}-${String(month.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}` : ""; }); const choose = (value: string) => { if (!value) return; window.dispatchEvent(new CustomEvent("operion-update-task-date", { detail: { taskId: task.id, ...(tab === "start" ? { assignedDate: value } : { dueDate: value }) } })); if (tab === "start") setTab("due"); else onClose(); }; const shift = (amount: number) => setMonth((value) => new Date(value.getFullYear(), value.getMonth() + amount, 1)); return <div className="task-date-picker" onClick={(event) => event.stopPropagation()}><div className="date-picker-tabs"><button className={tab === "start" ? "active" : ""} type="button" onClick={() => setTab("start")}>♧ Start date</button><button className={tab === "due" ? "active" : ""} type="button" onClick={() => setTab("due")}>Due date</button></div><div className="date-picker-month"><button type="button" onClick={() => shift(-1)} aria-label="Previous month">‹</button><strong>{new Intl.DateTimeFormat("en-US", { month: "long", year: "numeric" }).format(month)}</strong><button type="button" onClick={() => shift(1)} aria-label="Next month">›</button></div><div className="date-picker-weekdays">{["S", "M", "T", "W", "T", "F", "S"].map((day, index) => <span key={`${day}-${index}`}>{day}</span>)}</div><div className="date-picker-days">{cells.map((value, index) => <button className={value === selected ? "selected" : ""} type="button" key={`${value}-${index}`} disabled={!value} onClick={() => choose(value)}>{value ? Number(value.slice(-2)) : ""}</button>)}</div><div className="date-picker-footer"><button type="button" onClick={() => { window.dispatchEvent(new CustomEvent("operion-update-task-date", { detail: { taskId: task.id, ...(tab === "start" ? { assignedDate: "" } : { dueDate: "" }) } })); onClose(); }}>Clear</button></div></div>; }

function MyTasksCard({ tasks, employer, lookup }: { tasks: TaskRecord[]; employer: boolean; lookup: Map<string, UserRecord> }) { const allProjects = load<WorkspaceRecord[]>(KEYS.workspaces, []).flatMap((item) => item.projects ?? []); const [filter, setFilter] = useState<TaskStatus>("assigned"); const [detailTask, setDetailTask] = useState<TaskRecord | null>(null); const [dateTaskId, setDateTaskId] = useState<string | null>(null); const filtered = sortTasksByDueDate(tasks.filter((task) => task.status === filter)); const overdue = tasks.filter((task) => task.status !== "completed" && parseDate(task.dueDate) < parseDate(today())).length; useEffect(() => { const open = (event: Event) => { const taskId = (event as CustomEvent<string>).detail; const task = tasks.find((item) => item.id === taskId); if (task) setDetailTask(task); }; const openDate = (event: Event) => setDateTaskId((event as CustomEvent<string>).detail); window.addEventListener("operion-open-task", open); window.addEventListener("operion-show-task-date", openDate); return () => { window.removeEventListener("operion-open-task", open); window.removeEventListener("operion-show-task-date", openDate); }; }, [tasks]); useEffect(() => { if (detailTask) setDetailTask(tasks.find((item) => item.id === detailTask.id) ?? null); }, [tasks]); const cycle = (task: TaskRecord) => { const next = task.status === "assigned" ? "ongoing" : task.status === "ongoing" ? "completed" : "assigned"; window.dispatchEvent(new CustomEvent("operion-update-task", { detail: { taskId: task.id, status: next } })); }; return <><section className="dashboard-card task-summary"><div className="dashboard-card-head"><div><span className="avatar-dot">{initials(employer ? "Me" : "You")}</span><h3>My tasks</h3><span className="privacy-mark" title="Private">●</span></div><span className="more-button">•••</span></div><div className="summary-tabs"><button className={filter === "assigned" ? "selected" : ""} type="button" onClick={() => setFilter("assigned")}>Assigned</button><button className={filter === "ongoing" ? "selected" : ""} type="button" onClick={() => setFilter("ongoing")}>Ongoing</button><button className={filter === "completed" ? "selected" : ""} type="button" onClick={() => setFilter("completed")}>Completed</button><span className="overdue-count">Overdue {overdue}</span></div><button className="inline-action" type="button" onClick={() => window.dispatchEvent(new CustomEvent("operion-create-task", { detail: "private" }))}><Plus size={17} />Create task</button><div className="task-summary-list">{filtered.length ? filtered.map((task) => <div className="summary-task" key={task.id} onClick={() => setDetailTask(task)}><button className={`task-check ${task.status}`} type="button" title="Change status" onClick={(event) => { event.stopPropagation(); cycle(task); }}>{task.status === "completed" ? "✓" : ""}</button><span className="summary-task-title">{task.title}</span>{task.createdBy && lookup.get(task.createdBy) && <span className="task-creator" title={`Created by ${lookup.get(task.createdBy)?.name}`}><span className="task-creator-avatar">{initials(lookup.get(task.createdBy)?.name ?? "")}</span><small>Created by {lookup.get(task.createdBy)?.name}</small></span>}{task.projectId && <span className="task-project-badge" title={allProjects.find((item) => item.id === task.projectId)?.name ?? "Project"}><LayoutGrid size={12} />{allProjects.find((item) => item.id === task.projectId)?.name ?? "Project"}</span>}<button className="due-date-button" type="button" onClick={(event) => { event.stopPropagation(); window.dispatchEvent(new CustomEvent("operion-open-task-date", { detail: task.id })); }}>{formatDate(task.dueDate)}</button>{dateTaskId === task.id && <DatePicker task={task} onClose={() => setDateTaskId(null)} />}</div>) : <div className="summary-empty">No {filter} tasks</div>}</div></section>{detailTask && <TaskDetailModal task={detailTask} lookup={lookup} onClose={() => setDetailTask(null)} onMarkComplete={() => { window.dispatchEvent(new CustomEvent("operion-update-task", { detail: { taskId: detailTask.id, status: "completed" } })); setDetailTask({ ...detailTask, status: "completed" }); }} />}</>; }

function TaskDetailDateButton({ task }: { task: TaskRecord }) { const [open, setOpen] = useState(false); return <div className="detail-date-picker-wrap"><button className="detail-value" type="button" onClick={() => setOpen((value) => !value)}>{formatDate(task.dueDate)}</button>{open && <DatePicker task={task} onClose={() => setOpen(false)} />}</div>; }

function TaskDetailModal({ task, lookup, onClose, onMarkComplete }: { task: TaskRecord; lookup: Map<string, UserRecord>; onClose: () => void; onMarkComplete: () => void }) { return <div className="task-detail-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="task-detail-modal" role="dialog" aria-modal="true"><div className="task-detail-toolbar"><button className="detail-action" type="button" onClick={onMarkComplete}>✓ Mark complete</button><button className="detail-delete" type="button" onClick={() => window.dispatchEvent(new CustomEvent("operion-delete-task", { detail: task.id }))}>Delete task</button><button className="icon-button" type="button" onClick={onClose} aria-label="Close"><X size={18} /></button></div>{task.isPrivate && <div className="private-strip">● <span>This task is private to you.</span></div>}<div className="task-detail-content"><h2>{task.title}</h2><div className="detail-field"><span>Assignee</span><strong className="detail-person">{taskAssignees(task, lookup).length ? taskAssignees(task, lookup).map((person) => <span className="detail-person" key={person.id}><span className="task-assignee-avatar">{initials(person.name)}</span>{person.name}</span>) : "Unassigned"}</strong></div><div className="detail-field"><span>Created by</span><strong className="detail-person">{task.createdBy && lookup.get(task.createdBy) ? <><span className="task-creator-avatar">{initials(lookup.get(task.createdBy)?.name ?? "")}</span>{lookup.get(task.createdBy)?.name}</> : "Unknown"}</strong></div><div className="detail-field"><span>Due date</span><TaskDetailDateButton task={task} /></div><div className="detail-field"><span>Projects</span><strong>{task.projectId ? "Project" : "General work"}</strong></div><h3>Description</h3><p>{task.description}</p><section className="detail-section"><div className="detail-section-head"><h3>Subtasks</h3><Plus size={18} /></div><div className="subtask-row">Add subtask <span>◌　◌</span></div></section><section className="detail-section attachments-section"><div className="detail-section-head"><h3>Attachments</h3><Plus size={18} /></div></section><section className="detail-section comments-section"><div className="comments-tabs"><strong>Comments</strong><span>All activity</span><small>↕ Oldest</small></div><div className="activity-row"><span className="task-creator-avatar">{task.createdBy && lookup.get(task.createdBy) ? initials(lookup.get(task.createdBy)?.name ?? "") : "?"}</span><span><strong>Task created</strong>{task.createdBy && lookup.get(task.createdBy) ? ` by ${lookup.get(task.createdBy)?.name}` : ""} · Activity</span></div></section></div><div className="comment-composer"><span className="task-creator-avatar">{task.createdBy && lookup.get(task.createdBy) ? initials(lookup.get(task.createdBy)?.name ?? "") : "?"}</span><textarea placeholder="Add a comment" rows={3} /></div></section></div>; }

function ProjectBoard({ employer, user, project, tasks, members, lookup, onAddTask, onMove, onReassign, dragTaskId, dropStatus, dropEmployeeId, setDragTaskId, setDropStatus, setDropEmployeeId, selectedEmployee, selectedEmployeeTasks, onSelectEmployee }: { employer: boolean; user: UserRecord; project: ProjectRecord | null; tasks: TaskRecord[]; members: UserRecord[]; lookup: Map<string, UserRecord>; onAddTask: () => void; onMove: (id: string, status: TaskStatus) => void; onReassign: (id: string, employeeId: string) => void; dragTaskId: string | null; dropStatus: TaskStatus | null; dropEmployeeId: string | null; setDragTaskId: (id: string | null) => void; setDropStatus: (status: TaskStatus | null) => void; setDropEmployeeId: (id: string | null) => void; selectedEmployee: UserRecord | null; selectedEmployeeTasks: TaskRecord[]; onSelectEmployee: (id: string) => void }) { const [projectView, setProjectView] = useState<"list" | "board" | "calendar" | "media">("list"); const [projectMenuOpen, setProjectMenuOpen] = useState(false); return <section className="board-stack"><div className="project-header"><div className="project-title"><span className="project-title-icon" style={{ background: project?.color }}><LayoutGrid size={20} /></span><div><h2>{project?.name}</h2></div></div><div className="project-people">{employer && <div className="project-menu-wrap"><button className="more-button" type="button" aria-label="Project actions" onClick={() => setProjectMenuOpen((open) => !open)}>•••</button>{projectMenuOpen && <div className="project-actions-menu"><button className="delete-project-button" type="button" onClick={() => { setProjectMenuOpen(false); window.dispatchEvent(new CustomEvent("operion-delete-project", { detail: project?.id })); }}>Delete project</button></div>}</div>} {!employer && <span className="more-button">•••</span>}</div></div><nav className="project-tabs" aria-label="Project views"><button className={projectView === "list" ? "active" : ""} type="button" onClick={() => setProjectView("list")}>List</button><button className={projectView === "board" ? "active" : ""} type="button" onClick={() => setProjectView("board")}>Board</button><button className={projectView === "calendar" ? "active" : ""} type="button" onClick={() => setProjectView("calendar")}>Calendar</button><button className={projectView === "media" ? "active" : ""} type="button" onClick={() => setProjectView("media")}>Media</button></nav><div className="board-toolbar">{employer && <button className="add-task-button" type="button" onClick={onAddTask}><Plus size={16} />Add task</button>}<div className="board-tools"><button type="button">Filter</button><button type="button">Sort</button><button type="button">Group</button><button type="button">Options</button><span>⌕</span></div></div>{employer && <section className="panel project-team-panel"><div className="panel-head"><div><p className="eyebrow">Team</p><h2>People on this project</h2></div><div className="panel-note">Drop a task on a team card to reassign it.</div></div><div className="employee-grid">{members.length ? members.map((member) => { const count = tasks.filter((task) => taskHasAssignee(task, member.id)).length; return <button className={`employee-card ${selectedEmployee?.id === member.id ? "active" : ""} ${dropEmployeeId === member.id ? "drop-active" : ""}`} key={member.id} type="button" onClick={() => onSelectEmployee(member.id)} onDragOver={(event) => { if (dragTaskId) { event.preventDefault(); setDropEmployeeId(member.id); } }} onDragLeave={() => setDropEmployeeId(null)} onDrop={(event) => { event.preventDefault(); if (dragTaskId) onReassign(dragTaskId, member.id); setDropEmployeeId(null); setDragTaskId(null); }}><span className="employee-avatar">{initials(member.name)}</span><span className="employee-body"><strong>{member.name}</strong><span>{member.designation}</span><small>{count} task{count === 1 ? "" : "s"}</small></span></button>; }) : <div className="empty-state">Add employees to assign project work.</div>}</div>{selectedEmployee && <div className="employee-detail"><p className="eyebrow">Selected employee</p><h3>{selectedEmployee.name} · {selectedEmployee.designation}</h3><div className="task-mini-list">{selectedEmployeeTasks.length ? selectedEmployeeTasks.map((task) => <div className="task-mini" key={task.id}><strong>{task.title}</strong><span>{statusLabel(task.status)}</span></div>) : <div className="empty-state small">No tasks assigned yet.</div>}</div></div>}</section>}<section className="panel board-panel"><div className="panel-head"><div><p className="eyebrow">{employer ? "Project" : "My project"}</p><h2>{projectView === "list" ? "Task list" : projectView === "board" ? "Board" : "Calendar"}</h2></div></div>{projectView === "list" ? <ProjectTaskList tasks={tasks} lookup={lookup} onMove={onMove} /> : projectView === "board" ? <TaskColumns tasks={tasks} lookup={lookup} dragTaskId={dragTaskId} dropStatus={dropStatus} setDragTaskId={setDragTaskId} setDropStatus={setDropStatus} onMove={onMove} /> : projectView === "calendar" ? <CalendarBoard tasks={tasks} lookup={lookup} /> : <MediaPanel project={project} />}</section></section>; }

function TaskColumns({ tasks, lookup, dragTaskId, dropStatus, setDragTaskId, setDropStatus, onMove }: { tasks: TaskRecord[]; lookup: Map<string, UserRecord>; dragTaskId: string | null; dropStatus: TaskStatus | null; setDragTaskId: (id: string | null) => void; setDropStatus: (status: TaskStatus | null) => void; onMove: (id: string, status: TaskStatus) => void }) { return <div className="task-board">{COLUMNS.map((column) => { const items = sortTasksByDueDate(tasks.filter((task) => task.status === column.status)); return <section className={`task-column ${dropStatus === column.status ? "drop-active" : ""}`} key={column.status} onDragOver={(event) => { if (dragTaskId) { event.preventDefault(); setDropStatus(column.status); } }} onDragLeave={() => setDropStatus(null)} onDrop={(event) => { event.preventDefault(); if (dragTaskId) onMove(dragTaskId, column.status); setDragTaskId(null); setDropStatus(null); }}><div className="column-head"><h3>{column.title}</h3><span>{items.length}</span></div><div className="task-list">{items.length ? items.map((task) => <TaskCard key={task.id} task={task} assignee={lookup.get(task.employeeId)} onDragStart={() => setDragTaskId(task.id)} onDragEnd={() => { setDragTaskId(null); setDropStatus(null); }} />) : <div className="empty-state small">Drop tasks here</div>}</div></section>; })}</div>; }

function ProjectTaskList({ tasks, lookup, onMove }: { tasks: TaskRecord[]; lookup: Map<string, UserRecord>; onMove: (id: string, status: TaskStatus) => void }) { const [sections, setSections] = useState([{ id: "general", name: "General work" }]); const session = load<{ email: string } | null>(KEYS.session, null); const currentUser = load<UserRecord[]>(KEYS.users, []).find((item) => item.email === normalizeEmail(session?.email ?? "")); const currentWorkspace = load<WorkspaceRecord[]>(KEYS.workspaces, []).find((item) => item.id === currentUser?.workspaceId); const readOnlyEmployeeId = currentUser?.role === "admin" ? currentWorkspace?.employerId ?? "" : ""; const [collapsed, setCollapsed] = useState<string[]>([]); const [assignments, setAssignments] = useState<Record<string, string>>({}); const [removedTaskIds, setRemovedTaskIds] = useState<string[]>([]); const [sectionDialog, setSectionDialog] = useState(false); const [deleteSection, setDeleteSection] = useState<{ id: string; name: string } | null>(null); const projectName = tasks[0]?.projectId ? load<WorkspaceRecord[]>(KEYS.workspaces, []).flatMap((workspace) => workspace.projects ?? []).find((project) => project.id === tasks[0].projectId)?.name ?? "Project tasks" : "General work"; const visibleTasks = tasks.filter((task) => !removedTaskIds.includes(task.id)); const addSection = () => setSectionDialog(true); const toggle = (sectionId: string) => setCollapsed((items) => items.includes(sectionId) ? items.filter((item) => item !== sectionId) : [...items, sectionId]); const dropTask = (event: DragEvent, sectionId: string) => { event.preventDefault(); const taskId = event.dataTransfer.getData("text/plain"); if (taskId) setAssignments((items) => ({ ...items, [taskId]: sectionId })); }; const confirmSectionDelete = () => { if (!deleteSection) return; const taskIds = visibleTasks.filter((task) => (assignments[task.id] ?? "general") === deleteSection.id).map((task) => task.id); setRemovedTaskIds((items) => [...items, ...taskIds]); if (taskIds.length) window.dispatchEvent(new CustomEvent("operion-delete-tasks-silently", { detail: taskIds })); setSections((items) => items.filter((section) => section.id !== deleteSection.id)); setDeleteSection(null); }; return <div className="project-task-list"><div className="project-list-head"><span>Name</span><span>Assignee</span><span>Created by</span><span>Due date</span></div>{sections.map((section, index) => { const sectionTasks = sortTasksByDueDate(visibleTasks.filter((task) => (assignments[task.id] ?? "general") === section.id)); return <section className="project-list-section" key={section.id} onDragOver={(event) => event.preventDefault()} onDrop={(event) => dropTask(event, section.id)}><div className="project-list-group-head"><button className="section-collapse-button" type="button" onClick={() => toggle(section.id)} aria-expanded={!collapsed.includes(section.id)}><span className={`section-chevron ${collapsed.includes(section.id) ? "collapsed" : ""}`}>▾</span><strong>{index === 0 ? projectName : section.name}</strong><small>{sectionTasks.length}</small></button>{index > 0 && <button className="section-delete-button" type="button" onClick={() => setDeleteSection(section)} aria-label={`Delete ${section.name}`}>×</button>}</div>{!collapsed.includes(section.id) && <>{sectionTasks.length ? sectionTasks.map((task) => <button className="project-task-row" draggable={!readOnlyEmployeeId || !taskHasAssignee(task, readOnlyEmployeeId)} type="button" key={task.id} onDragStart={(event) => { event.dataTransfer.setData("text/plain", task.id); }} onClick={(event) => event.preventDefault()}><span className={`list-task-check ${task.status} ${readOnlyEmployeeId && taskHasAssignee(task, readOnlyEmployeeId) ? "read-only" : ""}`} role="button" tabIndex={0} onClick={(event) => { event.stopPropagation(); if (!readOnlyEmployeeId || !taskHasAssignee(task, readOnlyEmployeeId)) onMove(task.id, task.status === "assigned" ? "ongoing" : task.status === "ongoing" ? "completed" : "assigned"); }} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); event.stopPropagation(); if (!readOnlyEmployeeId || !taskHasAssignee(task, readOnlyEmployeeId)) onMove(task.id, task.status === "assigned" ? "ongoing" : task.status === "ongoing" ? "completed" : "assigned"); } }}>{task.status === "completed" ? "✓" : ""}</span><span className="list-task-name">{task.title}</span><span className="list-assignees">{taskAssignees(task, lookup).map((person, index) => <span className="task-assignee-avatar" style={{ zIndex: taskAssignees(task, lookup).length - index }} title={person.name} key={person.id}>{initials(person.name)}</span>)}</span><span className="list-creators">{task.createdBy && lookup.get(task.createdBy) ? <span className="task-assignee-avatar" title={lookup.get(task.createdBy)?.name}>{initials(lookup.get(task.createdBy)?.name ?? "")}</span> : "-"}</span><span className={`list-due ${parseDate(task.dueDate) < parseDate(today()) && task.status !== "completed" ? "overdue" : ""}`}>{formatDate(task.dueDate)}</span></button>) : <div className="empty-state small">{index === 0 ? "Add a task to this project." : "Drop tasks here."}</div>}</>}</section>; })}<button className="add-section-button" type="button" onClick={addSection}><Plus size={17} />Add section</button>{sectionDialog && <Modal title="Add section" onClose={() => setSectionDialog(false)}><form className="stack" onSubmit={(event) => { event.preventDefault(); const name = value(new FormData(event.currentTarget), "sectionName"); if (!name) return; setSections((items) => [...items, { id: id(), name }]); setSectionDialog(false); event.currentTarget.reset(); }}><input name="sectionName" placeholder="Section name" autoFocus required /><div className="confirm-actions"><button className="secondary-button" type="button" onClick={() => setSectionDialog(false)}>Cancel</button><button className="primary-button" type="submit">Add section</button></div></form></Modal>}{deleteSection && <Modal title="Delete section" onClose={() => setDeleteSection(null)}><p className="confirm-message">Delete {deleteSection.name} and all tasks under it?</p><div className="confirm-actions"><button className="secondary-button" type="button" onClick={() => setDeleteSection(null)}>Cancel</button><button className="danger-button" type="button" onClick={confirmSectionDelete}>Delete section</button></div></Modal>}</div>; }

function CalendarBoard({ tasks, lookup }: { tasks: TaskRecord[]; lookup: Map<string, UserRecord> }) { const days = useMemo(() => weekCalendarDays(tasks), [tasks]); const columns = "repeat(7, minmax(132px, 1fr))"; return <section className="panel week-calendar-panel"><div className="calendar-toolbar"><div className="calendar-month"><button type="button" aria-label="Previous week">‹</button><button type="button">Today</button><button type="button" aria-label="Next week">›</button><strong>{formatMonth(days[0].iso)}</strong></div><div className="calendar-tools"><span>No date ({tasks.filter((task) => !task.dueDate).length})</span><span>⊕ Weeks</span><span>☰ Filter</span><span>⌘ Options</span><span>⌕</span></div></div>{tasks.length ? <div className="calendar-wrap week-calendar"><div className="week-header" style={{ gridTemplateColumns: columns }}>{days.map((day) => <div className={`week-day-head ${day.iso === today() ? "today" : ""}`} key={day.iso}><strong>{day.label}</strong><span>{day.shortDate}</span></div>)}</div><div className="week-body" style={{ gridTemplateColumns: columns }}>{days.map((day) => <div className="week-day-cell" key={day.iso} />)}{tasks.map((task) => { const start = Math.max(0, dayIndex(task.assignedDate, days[0].iso)); const end = Math.min(6, dayIndex(task.dueDate || task.assignedDate, days[0].iso)); return <div className="week-task-bar" key={task.id} style={{ gridColumn: `${start + 1} / ${end + 2}`, background: deadlineGradient(task.assignedDate, task.dueDate) }} title={`${task.title} · ${lookup.get(task.employeeId)?.name ?? "Unassigned"}`}><span>{task.title}</span><small>{formatDate(task.assignedDate)} - {formatDate(task.dueDate)}</small></div>; })}</div></div> : <div className="empty-state">Add project tasks to see them on the calendar.</div>}</section>; }
function TaskCard({ task, assignee, onDragStart, onDragEnd }: { task: TaskRecord; assignee?: UserRecord; onDragStart: () => void; onDragEnd: () => void }) { return <article className={`task-card ${task.status}`} draggable onDragStart={(event) => { event.dataTransfer.effectAllowed = "move"; event.dataTransfer.setData("text/plain", task.id); onDragStart(); }} onDragEnd={onDragEnd}><div className="task-card-top"><span className={`status-pill ${task.status}`}>{statusLabel(task.status)}</span><span className={`priority-pill ${task.priority ?? "medium"}`}>{priorityLabel(task.priority)}</span><GripVertical size={16} /></div><h4>{task.title}</h4><p>{task.description}</p><div className="task-meta"><span>{assignee?.name ?? "No assignee"}</span><span>{formatDate(task.dueDate)}</span></div></article>; }
function ProjectAssetFields() { const [fields, setFields] = useState<{ id: string; type: "file" | "link" }[]>([{ id: id(), type: "file" }, { id: id(), type: "link" }]); const add = (type: "file" | "link") => setFields((items) => [...items, { id: id(), type }]); const remove = (fieldId: string) => setFields((items) => items.filter((item) => item.id !== fieldId)); return <div className="project-asset-fields"><div className="asset-field-group"><label>Files</label>{fields.filter((field) => field.type === "file").map((field, index) => <div className="asset-field-row" key={field.id}><input id={index === 0 ? "project-files" : undefined} data-project-file type="file" multiple accept="image/*,video/*,.csv,.xls,.xlsx,.pdf,.doc,.docx" />{index === 0 ? <button className="asset-add-button" type="button" onClick={() => add("file")} aria-label="Add file field"><Plus size={18} /></button> : <button className="asset-remove-button" type="button" onClick={() => remove(field.id)} aria-label="Remove file field"><X size={17} /></button>}</div>)}</div><div className="asset-field-group"><label>Link</label>{fields.filter((field) => field.type === "link").map((field, index) => <div className="asset-field-row" key={field.id}><input id={index === 0 ? "project-link" : undefined} data-project-link type="url" placeholder="https://" />{index === 0 ? <button className="asset-add-button" type="button" onClick={() => add("link")} aria-label="Add link field"><Plus size={18} /></button> : <button className="asset-remove-button" type="button" onClick={() => remove(field.id)} aria-label="Remove link field"><X size={17} /></button>}</div>)}</div></div>; }

function AssigneeDragPicker({ people, selectedIds, setSelectedIds }: { people: UserRecord[]; selectedIds: string[]; setSelectedIds: (ids: string[]) => void }) { const selected = people.filter((person) => selectedIds.includes(person.id)); const available = people.filter((person) => !selectedIds.includes(person.id)); const move = (personId: string, include: boolean) => setSelectedIds(include ? [...selectedIds, personId] : selectedIds.filter((id) => id !== personId)); const dragStart = (event: DragEvent<HTMLDivElement>, personId: string) => { event.dataTransfer.setData("text/plain", personId); event.dataTransfer.effectAllowed = "move"; }; const drop = (event: DragEvent<HTMLDivElement>, include: boolean) => { event.preventDefault(); const personId = event.dataTransfer.getData("text/plain"); if (personId) move(personId, include); }; const tile = (person: UserRecord, include: boolean) => <div className="employee-drag-tile" draggable onDragStart={(event) => dragStart(event, person.id)} key={person.id}><span className="employee-drag-avatar">{initials(person.name)}</span><span><strong>{person.name}</strong><small>{person.designation}</small></span><button type="button" onClick={() => move(person.id, !include)} aria-label={include ? `Remove ${person.name}` : `Assign ${person.name}`}>{include ? "×" : "+"}</button></div>; return <div className="assignee-drag-picker"><div className="assignee-drag-zone" onDragOver={(event) => event.preventDefault()} onDrop={(event) => drop(event, false)}><div className="assignee-zone-head"><strong>Employees</strong><small>Drag to assign</small></div>{available.length ? available.map((person) => tile(person, false)) : <p className="assignee-zone-empty">All employees selected</p>}</div><div className="assignee-drag-zone selected" onDragOver={(event) => event.preventDefault()} onDrop={(event) => drop(event, true)}>{selected.map((person) => <input type="hidden" name="employeeId" value={person.id} key={`hidden-${person.id}`} />)}<div className="assignee-zone-head"><strong>Assigned</strong><small>{selected.length} selected</small></div>{selected.length ? selected.map((person) => tile(person, true)) : <p className="assignee-zone-empty">Drop employees here</p>}</div></div>; }

function TaskCreationModal({ taskProjectId, project, projects, employer, user, members, assigneeIds, setAssigneeIds, onClose, onSubmit }: { taskProjectId: string | null | undefined; project: ProjectRecord | null; projects: ProjectRecord[]; employer: boolean; user: UserRecord; members: UserRecord[]; assigneeIds: string[]; setAssigneeIds: (ids: string[]) => void; onClose: () => void; onSubmit: (event: FormEvent<HTMLFormElement>) => void }) { const selectedPeople = [...(employer ? [user] : []), ...members.filter((member) => member.id !== user.id)]; return <Modal title="Create task" onClose={onClose} className="task-create-modal"><form className="stack task-create-form" onSubmit={onSubmit}><div className="task-form-grid"><label>Task name <span>*</span><div className="task-input-with-icon"><BriefcaseBusiness size={17} /><input name="title" placeholder="Enter a clear and concise task name" required /></div></label>{taskProjectId !== null && <label>Project{taskProjectId !== undefined ? <div className="task-input-with-icon"><BriefcaseBusiness size={17} /><div className="task-project-fixed">{projects.find((item) => item.id === taskProjectId)?.name ?? "Project"}</div></div> : <select name="projectId" defaultValue="" required><option value="" disabled>Select project</option>{projects.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select>}</label>}</div><label>Description<div className="task-description"><div className="description-tools"><button type="button"><Bold size={16} /></button><button type="button"><Italic size={16} /></button><button type="button"><Underline size={16} /></button><button type="button"><List size={16} /></button><button type="button"><ListOrdered size={16} /></button><button type="button"><Link2 size={16} /></button></div><textarea name="description" placeholder="Write details about the task..." rows={4} required /></div></label><div className="task-form-grid"><label>Start date <span>*</span><input name="assignedDate" type="date" defaultValue={today()} required /></label><label>Due date <span>*</span><input name="dueDate" type="date" required /></label></div>{taskProjectId !== null && <label>Assignees <span>*</span><AssigneeDragPicker people={selectedPeople} selectedIds={assigneeIds} setSelectedIds={setAssigneeIds} /></label>}<div className="task-form-footer"><label className="reminder-toggle"><input type="checkbox" />Set reminder <Bell size={16} /></label><div><button className="secondary-button" type="button" onClick={onClose}>Cancel</button><button className="primary-button" type="submit" disabled={taskProjectId !== null && !assigneeIds.length}><Plus size={16} />Create task<ArrowRight size={16} /></button></div></div></form></Modal>; }

function Modal({ title, onClose, children, className = "" }: { title: string; onClose: () => void; children: ReactNode; className?: string }) { useEffect(() => { const previousOverflow = document.body.style.overflow; document.body.style.overflow = "hidden"; return () => { document.body.style.overflow = previousOverflow; }; }, []); return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className={`modal-card ${className}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><div><h2>{title}</h2>{title === "Create task" && <p className="modal-subtitle">Add a new task to bring work forward.</p>}</div><button className="icon-button" type="button" onClick={onClose} aria-label="Close"><X size={18} /></button></div>{children}{title === "Create project" && <ProjectAssetFields />}</section></div>; }
function MediaPanel({ project }: { project: ProjectRecord | null }) { const attachments = project?.attachments ?? []; return <section className="media-panel">{attachments.length ? <div className="media-grid">{attachments.map((attachment) => attachment.kind === "link" && attachment.url ? <a className="media-card" href={attachment.url} target="_blank" rel="noreferrer" key={attachment.id}><span className="media-card-icon">↗</span><strong>{attachment.name}</strong><small>Link</small></a> : <div className="media-card" key={attachment.id}><span className="media-card-icon">▣</span><strong>{attachment.name}</strong><small>{attachment.kind || "File"}</small>{attachment.url ? <a className="media-download-button" href={attachment.url} download={attachment.name}>Download</a> : <small className="media-download-unavailable">Download unavailable for older upload</small>}</div>)}</div> : <div className="empty-state">No media has been added to this project yet.</div>}</section>; }

function getProjects(workspace: WorkspaceRecord): ProjectRecord[] { return workspace.projects?.length ? workspace.projects : [{ id: defaultProjectId(workspace.id), name: "General work", description: "Tasks created before projects were added", color: "#e2e8f0" }]; }
function defaultProjectId(workspaceId: string) { return `${workspaceId}-general`; }
function usePersistentState<T>(key: string, fallback: T) { const [state, setState] = useState<T>(() => load(key, fallback)); useEffect(() => { window.localStorage.setItem(key, JSON.stringify(state)); }, [key, state]); return [state, setState] as const; }
function load<T>(key: string, fallback: T) { try { const raw = window.localStorage.getItem(key); return raw ? JSON.parse(raw) as T : fallback; } catch { return fallback; } }
function value(form: FormData, name: string) { const item = form.get(name); return typeof item === "string" ? item.trim() : ""; }
function readFileData(file: File) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : ""); reader.onerror = () => reject(reader.error); reader.readAsDataURL(file); }); }
function findUser(users: UserRecord[], email: string) { return users.find((user) => user.email === normalizeEmail(email)) ?? null; }
function normalizeEmail(email: string) { return email.trim().toLowerCase(); }
function id() { return crypto.randomUUID(); }
function today() { return new Date().toISOString().slice(0, 10); }
function parseDate(value: string) { return new Date(`${value}T00:00:00`); }
function sortTasksByDueDate(tasks: TaskRecord[]) { return [...tasks].sort((a, b) => { if (!a.dueDate && !b.dueDate) return a.title.localeCompare(b.title); if (!a.dueDate) return 1; if (!b.dueDate) return -1; return parseDate(a.dueDate).getTime() - parseDate(b.dueDate).getTime() || a.title.localeCompare(b.title); }); }
function weekCalendarDays(tasks: TaskRecord[]) { const anchor = tasks.length ? parseDate(tasks[0].assignedDate) : parseDate(today()); const start = new Date(anchor); start.setDate(anchor.getDate() - anchor.getDay()); return Array.from({ length: 7 }, (_, index) => { const date = addDays(start, index); return { iso: date.toISOString().slice(0, 10), label: new Intl.DateTimeFormat("en-US", { weekday: "short" }).format(date).toUpperCase(), shortDate: new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(date) }; }); }
function formatMonth(value: string) { return new Intl.DateTimeFormat("en-US", { month: "long", year: "numeric" }).format(parseDate(value)); }
function calendarDays(tasks: TaskRecord[]) { const start = tasks.length ? tasks.reduce((low, task) => parseDate(task.assignedDate) < low ? parseDate(task.assignedDate) : low, parseDate(tasks[0].assignedDate)) : parseDate(today()); const end = tasks.length ? tasks.reduce((high, task) => parseDate(task.dueDate) > high ? parseDate(task.dueDate) : high, parseDate(tasks[0].dueDate)) : addDays(start, 6); const result: { iso: string; label: string; shortDate: string }[] = []; const cursor = addDays(start, -1); while (cursor <= addDays(end, 1)) { result.push({ iso: cursor.toISOString().slice(0, 10), label: new Intl.DateTimeFormat("en-US", { weekday: "short" }).format(cursor), shortDate: new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(cursor) }); cursor.setDate(cursor.getDate() + 1); } return result; }
function addDays(date: Date, days: number) { const next = new Date(date); next.setDate(next.getDate() + days); return next; }
function dayIndex(value: string, start: string) { return Math.max(0, Math.round((parseDate(value).getTime() - parseDate(start).getTime()) / 86400000)); }
function formatDate(value: string) { return new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(parseDate(value)); }
function deadlineGradient(startValue: string, dueValue: string) { const start = parseDate(startValue), due = parseDate(dueValue), progress = Math.min(1, Math.max(0, (parseDate(today()).getTime() - start.getTime()) / Math.max(1, due.getTime() - start.getTime()))), hue = 120 - progress * 120; return `linear-gradient(90deg, hsl(${hue} 70% 42%), hsl(${Math.max(0, hue - 10)} 72% 34%))`; }
function taskAssignees(task: TaskRecord, lookup: Map<string, UserRecord>) { return (task.employeeIds?.length ? task.employeeIds : [task.employeeId]).map((employeeId) => lookup.get(employeeId)).filter((person): person is UserRecord => Boolean(person)); }
function statusLabel(status: TaskStatus) { return status === "assigned" ? "Assigned" : status === "ongoing" ? "Ongoing" : "Completed"; }
function priorityLabel(priority: TaskPriority | undefined) { return priority === "high" ? "High priority" : priority === "low" ? "Low priority" : "Medium priority"; }
function initials(name: string) { return name.split(/\s+/).filter(Boolean).map((part) => part[0] ?? "").join("").slice(0, 2).toUpperCase(); }
function Sidebar({ collapsed, onToggle, employer, owner, projects, activeProjectId, onHome, onProjects, onOpenProject, onInvite }: { collapsed: boolean; onToggle: () => void; employer: boolean; owner: boolean; projects: ProjectRecord[]; activeProjectId: string; onHome: () => void; onProjects: () => void; onOpenProject: (id: string) => void; onInvite: () => void }) { const [projectsOpen, setProjectsOpen] = useState(true); return <aside className="sidebar"><div className="sidebar-brand"><span>Operion</span><button className="sidebar-collapse-button" type="button" onClick={onToggle} aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"} title={collapsed ? "Expand sidebar" : "Collapse sidebar"}><Menu size={18} /></button></div><div className="sidebar-label">Work</div><nav className="sidebar-nav"><button className="sidebar-nav-item active" type="button" onClick={onHome}><LayoutGrid size={18} />Home</button><button className="sidebar-nav-item" type="button"><span className="nav-icon">◌</span>Inbox</button></nav><div className="sidebar-divider" /><nav className="sidebar-nav"><button className="sidebar-nav-item" type="button"><CheckCircle2 size={18} />My tasks</button><button className="sidebar-nav-item" type="button" onClick={onProjects}><LayoutGrid size={18} />Projects</button></nav><div className="sidebar-label project-label"><button className={`project-toggle ${projectsOpen ? "open" : ""}`} type="button" onClick={() => setProjectsOpen((open) => !open)} aria-expanded={projectsOpen} aria-label={projectsOpen ? "Collapse projects" : "Expand projects"}><span>▾</span><span>Work</span></button><Plus size={15} /></div>{projectsOpen && <div className="sidebar-projects">{projects.map((project, index) => <button className={`sidebar-project ${project.id === activeProjectId ? "active" : ""}`} key={project.id} type="button" onClick={() => onOpenProject(project.id)}><span className="sidebar-project-icon" style={{ background: COLORS[index % COLORS.length] }}><LayoutGrid size={14} /></span><span>{project.name}</span></button>)}</div>}{owner && <button className="sidebar-invite" type="button" onClick={onInvite}><UserPlus size={16} />Invite</button>}</aside>; }

export default ProjectMvpApp;
